import {GEAR_CATALOG,BASE_GEAR,buyGear,restock,settleFish,cargoWeight,carriedWeight,equipmentStats} from './equipment.js';
const $=selector=>document.querySelector(selector);
export function createCommerce({state:s,openModal,closeModal,toast,save,onPacked,launchBoat,staffName}){
 const shore=()=>s.mode==='walk'&&Math.hypot(s.playerX-1.5,s.playerZ+53)<12;
 function showStaff(){if(!shore()){toast('回到租船柜台旁，可整理储物柜、兑换鱼获和补给。');return;}
  openModal('staff',`<div class="eyebrow">15 MUNICIPAL WHARF / 码头柜台</div><h2 id="modal-title">${staffName}</h2><p class="sub">整理装备、安排吊艇，或者谈谈这趟海上的收获。</p><div class="account-strip"><strong>${s.profile.credits} 潮汐点</strong><span>待兑换鱼获 ${cargoWeight(s.catches).toFixed(2)} kg</span></div><div class="touch-menu-grid"><button id="staff-pack">整理装备与储物柜</button><button id="staff-launch">${s.launchStage==='afloat'?'吊臂回收空艇':'请求吊臂下放木艇'}</button><button id="staff-trade">鱼获兑换 · 虚拟点数</button><button id="staff-shop">浏览装备商店</button><button id="staff-free">免费补齐基础包</button><button id="staff-return">回到码头</button></div><p class="sub fine-print">角色交互与潮汐点为游戏系统。真实租船商家的公开信息不代表其提供鱼获收购、积分或游戏中的服务。</p>`);
  $('#staff-pack').onclick=()=>showInventory();$('#staff-shop').onclick=showShop;$('#staff-launch').onclick=()=>{closeModal();launchBoat();};$('#staff-return').onclick=closeModal;
  $('#staff-free').onclick=()=>{restock(s.profile);s.fuel=100;save();showStaff();toast('鱿鱼条、备用软饵、饮水与基础装备已免费补齐，油箱已补给。');};
  $('#staff-trade').onclick=()=>{let total=0,count=0;for(const fish of s.catches){if(fish.kept&&!fish.settled){const value=settleFish(s.profile,fish);if(value){total+=value;count++;}}}save();showStaff();toast(count?`已兑换 ${count} 条虚拟鱼获，获得 ${total} 潮汐点。`:'冷藏箱里没有尚未兑换的鱼获。');};
 }
 function showShop(){if(!shore())return;const cards=GEAR_CATALOG.filter(g=>g.price>0).map(g=>{const owned=g.slot!=='consumable'&&s.profile.owned.includes(g.id);return `<article class="shop-item"><div><strong>${g.name}</strong><p>${g.desc}</p><small>${g.kg} kg${g.bait?' · 库存 '+(s.profile.stock[g.bait]||0):' · 兑换后存入储物柜'}</small></div><button class="secondary" data-buy="${g.id}" ${owned?'disabled':''}>${owned?'已拥有':g.price+' 点 · 兑换'}</button></article>`;}).join('');
  const scroll=$('#modal').scrollTop;openModal('shop',`<div class="eyebrow">TIDAL OUTFITTER / 虚拟装备商店</div><h2 id="modal-title">合适，比昂贵更重要。</h2><div class="account-strip"><strong id="shop-credit">${s.profile.credits} 潮汐点</strong><button class="text-btn" id="shop-back">返回柜台</button></div><p class="sub">基础套装可以钓获这里的所有鱼种。升级改变灵敏度、泄力和容量，鱼讯由水域、鱼饵、呈饵方式与运气共同决定。</p><div class="shop-list">${cards}</div><p class="sub fine-print">潮汐点仅为游戏积分，无现金价值。价格、载荷与效果是模拟参数。</p>`);$('#modal').scrollTop=scroll;
  $('#shop-back').onclick=showStaff;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const result=buyGear(s.profile,b.dataset.buy);if(result.ok){save();showShop();}toast(result.message);});
 }
 function showInventory(){if(s.mode==='intro')return;if(s.mode==='walk'){if(!shore()){toast('在租船柜台旁打开储物柜。船上的装备会保留到返航。');return;}const items=GEAR_CATALOG.filter(g=>s.profile.owned.includes(g.id)&&g.slot!=='consumable');
  openModal('gear',`<div class="eyebrow">YOUR LOCKER / 装备自由搭配</div><h2 id="modal-title">这一趟，带上什么？</h2><p class="sub">基础装备免费。自由选择随身装备；鱼竿与基础钓组用于钓鱼，救生衣穿戴状态会影响落水表现。</p><button class="secondary" id="pack-starter">一键带上免费基础套装</button><div class="gear-grid" style="margin-top:14px">${items.map(g=>`<button class="gear-item ${s.packed.includes(g.id)?'packed':''}" data-gear="${g.id}" aria-pressed="${s.packed.includes(g.id)}"><span class="gear-icon">${g.icon||'◇'}</span><span><strong>${g.name}</strong><small>${g.kg} kg · ${g.desc}</small></span><span class="tick">${s.packed.includes(g.id)?'✓':'+'}</span></button>`).join('')}</div><div class="modal-foot"><span id="packing-count">${s.packed.length} 件 · ${carriedWeight(s.packed,s.profile).toFixed(1)} kg</span><button class="primary" id="finish-packing">带上所选装备 →</button><button class="text-btn" id="gear-shop">看看装备商店</button></div>`);
  function refresh(){document.querySelectorAll('[data-gear]').forEach(b=>{const chosen=s.packed.includes(b.dataset.gear);b.classList.toggle('packed',chosen);b.setAttribute('aria-pressed',String(chosen));b.querySelector('.tick').textContent=chosen?'✓':'+';});$('#packing-count').textContent=`${s.packed.length} 件 · ${carriedWeight(s.packed,s.profile).toFixed(1)} kg`;s.pfd=s.packed.includes('pfd');save();}
  document.querySelectorAll('[data-gear]').forEach(b=>b.onclick=()=>{const id=b.dataset.gear;s.packed=s.packed.includes(id)?s.packed.filter(g=>g!==id):[...s.packed,id];refresh();});
  $('#pack-starter').onclick=()=>{s.packed=[...new Set([...s.packed,...BASE_GEAR.map(g=>g.id)])];refresh();};$('#finish-packing').onclick=()=>{closeModal();onPacked();save();};$('#gear-shop').onclick=showShop;
 }else showRig();}
 function showRig(){const rigOptions=[['bottom','沉底钓组','tackle'],['slider','滑铅漂钓','rig_slider'],['jig','铅头软饵','rig_jig'],['float','浮游钓组','rig_float']];const baitNames={squid:'鱿鱼条',anchovy:'鳀鱼饵',shrimp:'虾饵',sardine:'沙丁鱼饵',jig:'软饵'};const rods=GEAR_CATALOG.filter(g=>g.slot==='rod'&&s.packed.includes(g.id));const stats=equipmentStats(s.profile,s.packed);
  openModal('rig',`<div class="eyebrow">ON BOARD / 装备与呈饵</div><h2 id="modal-title">没有唯一正确的钓法。</h2><div class="equipment-row"><label for="rod-select">船竿</label><select id="rod-select">${rods.map(g=>`<option value="${g.id}" ${s.profile.loadout.rod===g.id?'selected':''}>${g.name}</option>`).join('')||'<option value="">没有携带鱼竿</option>'}</select></div><div class="equipment-row"><label for="rig-select">钓法</label><select id="rig-select">${rigOptions.map(([id,label,gear])=>`<option value="${id}" ${s.rig===id?'selected':''} ${s.packed.includes(gear)?'':'disabled'}>${label}${s.packed.includes(gear)?'':' · 储物柜未携带'}</option>`).join('')}</select></div><div class="equipment-row"><label for="bait-select">鱼饵</label><select id="bait-select">${Object.entries(baitNames).map(([id,label])=>`<option value="${id}" ${s.bait===id?'selected':''}>${label} · ${s.profile.stock[id]||0} 份</option>`).join('')}</select></div><div class="equipment-row"><label for="drag-select">泄力 <span id="drag-label">${Math.round(s.drag*100)}%</span></label><input type="range" id="drag-select" min="20" max="85" value="${s.drag*100}"></div><div class="equipment-row"><span>钩上鱼饵</span><span>${s.baitOnHook?baitNames[s.baitOnHook.kind]+' · 状态 '+Math.round(s.baitOnHook.condition*100)+'%':'尚未挂饵，抛出时使用一份'}</span></div><div class="equipment-row"><span>载荷 / 冷藏箱</span><span>${stats.weight.toFixed(1)} kg / ${cargoWeight(s.catches).toFixed(1)} / ${stats.capacity} kg</span></div><div class="equipment-row"><span>穿戴救生衣</span><button class="secondary" id="toggle-pfd">${s.pfd?'已穿好 · 脱下':'未穿 · 穿上'}</button></div><div class="equipment-row"><span>发动机熄火绳</span><button class="secondary" id="toggle-lanyard">${s.lanyard?'已系好 · 解开':'未系 · 系好'}</button></div><p class="sub fine-print">鱼饵不会每次收回就消失；已有钩饵会继续使用。落水时船上箱具留在船内。各项载荷与概率是游戏模型。</p><div class="modal-foot"><button class="primary" id="apply-rig">收好装备 ✓</button></div>`);
  $('#drag-select').oninput=e=>$('#drag-label').textContent=e.target.value+'%';$('#toggle-pfd').onclick=()=>{if(!s.packed.includes('pfd')){toast('救生衣在岸上储物柜，请返航免费领取。');return;}s.pfd=!s.pfd;$('#toggle-pfd').textContent=s.pfd?'已穿好 · 脱下':'未穿 · 穿上';save();};$('#toggle-lanyard').onclick=()=>{s.lanyard=!s.lanyard;$('#toggle-lanyard').textContent=s.lanyard?'已系好 · 解开':'未系 · 系好';save();};
  $('#apply-rig').onclick=()=>{if(s.fishState!=='idle'){toast('先收回鱼线，再更换船竿或钓组。搏鱼时可用屏幕上的 − / + 调泄力。');return;}const selectedRig=$('#rig-select').value;const required=rigOptions.find(r=>r[0]===selectedRig)?.[2];if(!required||!s.packed.includes(required)){toast('当前未携带这套钓组，请回柜台整理装备。');return;}s.profile.loadout.rod=$('#rod-select').value||'rod';s.profile.loadout.reel=s.packed.includes('reel_smooth')?'reel_smooth':null;s.profile.loadout.line=s.packed.includes('line_braid')?'line_braid':null;s.profile.loadout.leader=s.packed.includes('leader_heavy')?'leader_heavy':null;s.profile.loadout.cooler=s.packed.includes('cooler_large')?'cooler_large':'cooler';s.rig=selectedRig;s.bait=$('#bait-select').value;s.drag=Number($('#drag-select').value)/100;closeModal();save();toast('钓组已整理好。');};
 }
 return{showInventory,showRig,showStaff,showShop};
}
